def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); comp=[]
                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            q=(y+dy,x+dx)
                            if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]] and q not in seen:
                                seen.add(q); stack.append(q)
                comps.append(comp)
    comp=max(comps,key=len)
    r0=min(r for r,c in comp); r1=max(r for r,c in comp); c0=min(c for r,c in comp); c1=max(c for r,c in comp)
    cells=set(comp)
    return [[grid[r][c] if (r,c) in cells else 0 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
